SELECT COALESCE(MAX(sequence_no), 0) + 1
FROM ai_chat_message
WHERE session_id = #{sessionId}

SELECT id, session_id, role, content, sequence_no, create_time
FROM (
    SELECT id, session_id, role, content, sequence_no, create_time
    FROM ai_chat_message
    WHERE session_id = #{sessionId}
    ORDER BY sequence_no DESC
    LIMIT #{limit}
) AS recent_messages
ORDER BY sequence_no ASC

SELECT id, session_id, role, content, sequence_no, create_time
FROM (
    SELECT id, session_id, role, content, sequence_no, create_time
    FROM ai_chat_message
    WHERE session_id = #{sessionId}
      AND sequence_no <= #{sequenceNo}
    ORDER BY sequence_no DESC
    LIMIT #{limit}
) AS turn_messages
ORDER BY sequence_no ASC

SELECT assistant_message.session_id, user_message.content AS user_question, assistant_message.content AS ai_answer FROM ai_chat_message assistant_message LEFT JOIN ai_chat_message user_message ON user_message.id = ( SELECT candidate_user.id FROM ai_chat_message candidate_user WHERE candidate_user.session_id = assistant_message.session_id AND candidate_user.role = 'USER' AND candidate_user.sequence_no < assistant_message.sequence_no ORDER BY candidate_user.sequence_no DESC LIMIT 1 ) WHERE assistant_message.role = 'ASSISTANT' AND assistant_message.session_id IN
#{sessionId}
AND NOT EXISTS ( SELECT 1 FROM ai_chat_message newer_assistant WHERE newer_assistant.session_id = assistant_message.session_id AND newer_assistant.role = 'ASSISTANT' AND newer_assistant.sequence_no > assistant_message.sequence_no )
